<original_code>
#include <bits/stdc++.h>
#define endl '\n'
using namespace std;

const int N = 10;
const int FLOW_N = 2 * N * N + 2;
const int MAXV = FLOW_N + 1;
const int INF = 1000000000;

string grid[N];
int sci[N][N] = {};
int res[N][N] = {};
int inf_time[N][N] = {};
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};
int reach[N][N][N][N] = {};

vector<int> g_adj[MAXV];
int cap[MAXV][MAXV], flow[MAXV][MAXV], cur[MAXV], lvl[MAXV], parent[MAXV];

bool bfs_lvl(int s, int t) {
    memset(lvl, -1, sizeof lvl);
    lvl[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g_adj[u]) {
            if (cap[u][v] - flow[u][v] > 0 && lvl[v] == -1) {
                lvl[v] = lvl[u] + 1;
                q.push(v);
            }
        }
    }
    return lvl[t] != -1;
}

bool aug_dfs(int u, int t) {
    if (u == t) return true;
    for (int &i = cur[u]; i < (int)g_adj[u].size(); ++i) {
        int v = g_adj[u][i];
        if (lvl[v] == lvl[u] + 1 && cap[u][v] - flow[u][v] > 0 && aug_dfs(v, t)) {
            parent[v] = u;
            return true;
        }
    }
    return false;
}

void add_edge(int u, int v, int c) {
    g_adj[u].push_back(v);
    g_adj[v].push_back(u);
    cap[u][v] += c;
}

int max_flow_value(int s, int t) {
    int ans = 0;
    while (bfs_lvl(s, t)) {
        memset(cur, 0, sizeof cur);
        while (true) {
            memset(parent, -1, sizeof parent);
            parent[s] = 0;
            if (!aug_dfs(s, t)) break;
            int add = INF;
            for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                add = min(add, cap[u][v] - flow[u][v]);
            }
            for (int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                flow[u][v] += add;
                flow[v][u] -= add;
            }
            ans += add;
        }
    }
    return ans;
}

int id(int n, int i, int j, bool right) {
    return i * n + j + (right ? n * n : 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;
    string line;
    pair<int,int> explode;

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] == 'Y') grid[i][j] = 'Y';
            else if (line[j] == 'Z') {
                grid[i][j] = 'Z';
                explode = {i, j};
            } else {
                grid[i][j] = '.';
                sci[i][j] += line[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] != 'Y' && line[j] != 'Z') res[i][j] += line[j] - '0';
        }
    }

    memset(inf_time, -1, sizeof inf_time);
    inf_time[explode.first][explode.second] = 0;
    queue<pair<int,int>> q;
    q.push(explode);
    while (!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int ni = i + dx[d], nj = j + dy[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == '.' && inf_time[ni][nj] == -1) {
                inf_time[ni][nj] = inf_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }

    memset(reach, -1, sizeof reach);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] != '.') continue;
            reach[i][j][i][j] = 0;
            queue<pair<int,int>> q;
            q.push({i, j});
            while (!q.empty()) {
                int ii = q.front().first, jj = q.front().second;
                q.pop();
                if (inf_time[ii][jj] == -1 || reach[i][j][ii][jj] < inf_time[ii][jj]) {
                    for (int d = 0; d < 4; ++d) {
                        int ni = ii + dx[d], nj = jj + dy[d];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == '.'
                            && (inf_time[ni][nj] == -1 || reach[i][j][ii][jj] + 1 <= inf_time[ni][nj])
                            && reach[i][j][ni][nj] == -1) {
                            reach[i][j][ni][nj] = reach[i][j][ii][jj] + 1;
                            q.push({ni, nj});
                        }
                    }
                }
            }
        }
    }

    int src = 2 * n * n;
    int sink = src + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (sci[i][j]) add_edge(src, id(n, i, j, false), sci[i][j]);
            if (res[i][j]) add_edge(id(n, i, j, true), sink, res[i][j]);
            for (int ii = 0; ii < n; ++ii) {
                for (int jj = 0; jj < n; ++jj) {
                    if (reach[i][j][ii][jj] >= 0 && reach[i][j][ii][jj] <= t) {
                        add_edge(id(n, i, j, false), id(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }

    cout << max_flow_value(src, sink) << endl;
    return 0;
}
